use std::io::{self,BufRead,Write}; use brightdesk_rust_core::analyze_text;
fn decode_hex(s:&str)->Result<String,&'static str>{if s.len()&1==1{return Err("invalid_hex_length");}let mut b=Vec::with_capacity(s.len()/2);for p in s.as_bytes().chunks_exact(2){b.push((hex(p[0]).ok_or("invalid_hex_digit")?<<4)|hex(p[1]).ok_or("invalid_hex_digit")?);}String::from_utf8(b).map_err(|_|"invalid_utf8")}
fn hex(v:u8)->Option<u8>{match v{b'0'..=b'9'=>Some(v-b'0'),b'a'..=b'f'=>Some(v-b'a'+10),b'A'..=b'F'=>Some(v-b'A'+10),_=>None}}
fn main(){let stdin=io::stdin();let mut out=io::BufWriter::new(io::stdout().lock());for line in stdin.lock().lines(){let Ok(line)=line else{break};let Some((id,data))=line.split_once('\t')else{continue};if id.is_empty()||!id.bytes().all(|b|b.is_ascii_digit()){continue;}let result=match decode_hex(data){Ok(text)=>{let m=analyze_text(&text);format!("{id}\t{}\t{}\t{}",m.characters,m.words,m.lines)},Err(e)=>format!("{id}\tERROR\t{e}")};if writeln!(out,"{result}").is_err()||out.flush().is_err(){break;}}}
#[cfg(test)]mod tests{use super::decode_hex;#[test]fn decodes_unicode(){assert_eq!(decode_hex("436166c3a920e4b896e7958c").unwrap(),"Café 世界");}#[test]fn rejects_invalid_data(){assert_eq!(decode_hex("0"),Err("invalid_hex_length"));assert_eq!(decode_hex("zz"),Err("invalid_hex_digit"));assert_eq!(decode_hex("ff"),Err("invalid_utf8"));}}
